package com.pvmtracker;

import java.time.LocalDate;
import java.util.Collections;
import java.util.List;
import java.util.Map;

final class DailySummary
{
	final LocalDate date;
	final boolean completed;
	final Map<String, Integer> kills;
	final Map<String, Integer> startingKillCounts;
	final Map<String, Integer> endingKillCounts;
	final List<LootSummary> loot;
	final List<RaidSummary> raids;
	final int totalKills;
	final long trackedLootValue;
	final long confirmedValue;
	final Map<String, Long> manualAdjustments;
	final long totalAdjustment;
	final long totalValue;

	DailySummary(LocalDate date, boolean completed, Map<String, Integer> kills,
		Map<String, Integer> startingKillCounts, Map<String, Integer> endingKillCounts,
		List<LootSummary> loot, List<RaidSummary> raids, int totalKills,
		long trackedLootValue, long confirmedValue,
		Map<String, Long> manualAdjustments, long totalAdjustment, long totalValue)
	{
		this.date = date;
		this.completed = completed;
		this.kills = Collections.unmodifiableMap(kills);
		this.startingKillCounts = Collections.unmodifiableMap(startingKillCounts);
		this.endingKillCounts = Collections.unmodifiableMap(endingKillCounts);
		this.loot = Collections.unmodifiableList(loot);
		this.raids = Collections.unmodifiableList(raids);
		this.totalKills = totalKills;
		this.trackedLootValue = trackedLootValue;
		this.confirmedValue = confirmedValue;
		this.manualAdjustments = Collections.unmodifiableMap(manualAdjustments);
		this.totalAdjustment = totalAdjustment;
		this.totalValue = totalValue;
	}

	LootSummary findLoot(String source)
	{
		return loot.stream().filter(entry -> entry.source.equals(source)).findFirst().orElse(null);
	}

	RaidSummary findRaid(String source)
	{
		return raids.stream().filter(entry -> entry.source.equals(source)).findFirst().orElse(null);
	}

	long bossTrackedValue(String source)
	{
		LootSummary summary = findLoot(source);
		return summary == null ? 0L : summary.value;
	}

	long bossAdjustment(String source)
	{
		return manualAdjustments.getOrDefault(source, 0L);
	}

	long bossConfirmedValue(String source)
	{
		return bossConfirmedSaleValue(source) + bossAdjustment(source);
	}

	long bossConfirmedSaleValue(String source)
	{
		LootSummary summary = findLoot(source);
		return summary == null ? 0L : summary.confirmedValue;
	}

	static final class LootSummary
	{
		final String source;
		final int drops;
		final long value;
		final long confirmedValue;
		final List<ItemSummary> items;
		final List<ItemSummary> hiddenItems;

		LootSummary(String source, int drops, long value, long confirmedValue, List<ItemSummary> items,
			List<ItemSummary> hiddenItems)
		{
			this.source = source;
			this.drops = drops;
			this.value = value;
			this.confirmedValue = confirmedValue;
			this.items = Collections.unmodifiableList(items);
			this.hiddenItems = Collections.unmodifiableList(hiddenItems);
		}
	}

	static final class RaidSummary
	{
		final String source;
		final int completions;
		final long personalPoints;
		final int pointRecords;
		final long lootPoints;
		final long teamPoints;
		final int teamPointRecords;
		final Integer minimumRaidLevel;
		final Integer maximumRaidLevel;

		RaidSummary(String source, int completions, long personalPoints, int pointRecords, long lootPoints,
			long teamPoints, int teamPointRecords, Integer minimumRaidLevel, Integer maximumRaidLevel)
		{
			this.source = source;
			this.completions = completions;
			this.personalPoints = personalPoints;
			this.pointRecords = pointRecords;
			this.lootPoints = lootPoints;
			this.teamPoints = teamPoints;
			this.teamPointRecords = teamPointRecords;
			this.minimumRaidLevel = minimumRaidLevel;
			this.maximumRaidLevel = maximumRaidLevel;
		}
	}

	static final class ItemSummary
	{
		final int itemId;
		final String name;
		final long quantity;
		final long value;
		final long confirmedQuantity;
		final long confirmedValue;
		final long geConfirmedQuantity;
		final long geConfirmedValue;
		final long alchConfirmedQuantity;
		final long alchConfirmedValue;
		final boolean kept;
		final Long confirmedValueOverride;

		ItemSummary(int itemId, String name, long quantity, long value, long confirmedQuantity, long confirmedValue,
			long geConfirmedQuantity, long geConfirmedValue, long alchConfirmedQuantity, long alchConfirmedValue,
			boolean kept, Long confirmedValueOverride)
		{
			this.itemId = itemId;
			this.name = name;
			this.quantity = quantity;
			this.value = value;
			this.confirmedQuantity = confirmedQuantity;
			this.confirmedValue = confirmedValue;
			this.geConfirmedQuantity = geConfirmedQuantity;
			this.geConfirmedValue = geConfirmedValue;
			this.alchConfirmedQuantity = alchConfirmedQuantity;
			this.alchConfirmedValue = alchConfirmedValue;
			this.kept = kept;
			this.confirmedValueOverride = confirmedValueOverride;
		}

		@Override
		public String toString()
		{
			return name;
		}
	}
}

package com.pvmtracker;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeSet;
import java.util.stream.Collectors;

final class DailySummaryService
{
	List<DailySummary> build(TrackerData data, LocalDate today, boolean showEmptyDays)
	{
		TreeSet<LocalDate> dates = new TreeSet<>(Comparator.reverseOrder());
		data.kcDays.keySet().stream().map(LocalDate::parse).forEach(dates::add);
		data.lootDays.keySet().stream().map(LocalDate::parse).forEach(dates::add);
		data.raidCompletions.stream().map(raid -> LocalDate.parse(raid.date)).forEach(dates::add);
		dates.add(today);

		List<DailySummary> result = new ArrayList<>();
		for (LocalDate date : dates)
		{
			TrackerData.KcDay kcDay = data.kcDays.get(date.toString());
			Map<String, Integer> kills = kcDay == null
				? new LinkedHashMap<>() : new LinkedHashMap<>(kcDay.kills);
			Map<String, Integer> startingCounts = kcDay == null
				? new LinkedHashMap<>() : new LinkedHashMap<>(kcDay.startingKillCounts);
			Map<String, Integer> endingCounts = kcDay == null
				? new LinkedHashMap<>() : new LinkedHashMap<>(kcDay.endingKillCounts);
			TrackerData.LootDay lootDay = data.lootDays.get(date.toString());
			List<DailySummary.LootSummary> loot = summarizeLoot(data, lootDay);
			List<DailySummary.RaidSummary> raids = summarizeRaids(data, date);
			int totalKills = kills.values().stream().mapToInt(Integer::intValue).sum();
			long trackedLootValue = loot.stream().mapToLong(source -> source.value).sum();
			long confirmedSalesValue = loot.stream().mapToLong(source -> source.confirmedValue).sum();
			Map<String, Long> adjustments = lootDay == null
				? new LinkedHashMap<>() : new LinkedHashMap<>(lootDay.manualAdjustments);
			long totalAdjustment = adjustments.values().stream().mapToLong(Long::longValue).sum();
			long totalValue = trackedLootValue + totalAdjustment;
			long confirmedValue = confirmedSalesValue + totalAdjustment;
			boolean completed = date.isBefore(today);
			if (showEmptyDays || completed || totalKills > 0 || totalValue > 0 || !raids.isEmpty())
			{
				result.add(new DailySummary(date, completed,
					kills, startingCounts, endingCounts, loot, raids, totalKills,
					trackedLootValue, confirmedValue, adjustments, totalAdjustment, totalValue));
			}
		}
		return result;
	}

	private List<DailySummary.RaidSummary> summarizeRaids(TrackerData data, LocalDate date)
	{
		Map<String, RaidAccumulator> raids = new LinkedHashMap<>();
		for (TrackerData.RaidCompletion completion : data.raidCompletions)
		{
			if (!date.toString().equals(completion.date))
			{
				continue;
			}
			RaidAccumulator raid = raids.computeIfAbsent(completion.source, ignored -> new RaidAccumulator());
			raid.completions++;
			if (completion.personalPoints != null)
			{
				raid.personalPoints += completion.personalPoints;
				raid.pointRecords++;
			}
			if (completion.lootPoints != null)
			{
				raid.lootPoints += completion.lootPoints;
			}
			if (completion.teamPoints != null)
			{
				raid.teamPoints += completion.teamPoints;
				raid.teamPointRecords++;
			}
			if (completion.raidLevel != null)
			{
				raid.minimumRaidLevel = raid.minimumRaidLevel == null ? completion.raidLevel
					: Math.min(raid.minimumRaidLevel, completion.raidLevel);
				raid.maximumRaidLevel = raid.maximumRaidLevel == null ? completion.raidLevel
					: Math.max(raid.maximumRaidLevel, completion.raidLevel);
			}
		}
		return raids.entrySet().stream().map(entry ->
		{
			RaidAccumulator raid = entry.getValue();
			return new DailySummary.RaidSummary(entry.getKey(), raid.completions, raid.personalPoints,
				raid.pointRecords, raid.lootPoints, raid.teamPoints, raid.teamPointRecords,
				raid.minimumRaidLevel, raid.maximumRaidLevel);
		}).collect(Collectors.toList());
	}

	private List<DailySummary.LootSummary> summarizeLoot(TrackerData data, TrackerData.LootDay day)
	{
		if (day == null)
		{
			return new ArrayList<>();
		}
		return day.sources.entrySet().stream()
			.map(entry ->
			{
				TrackerData.LootSource source = entry.getValue();
				List<DailySummary.ItemSummary> items = source.items.values().stream()
					.filter(item -> !data.isLootHidden(entry.getKey(), item.itemId))
					.sorted(Comparator.comparingLong((TrackerData.LootItem item) -> item.totalValue).reversed())
					.map(item -> itemSummary(item))
					.collect(Collectors.toList());
				List<DailySummary.ItemSummary> hiddenItems = source.items.values().stream()
					.filter(item -> data.isLootHidden(entry.getKey(), item.itemId))
					.sorted(Comparator.comparing((TrackerData.LootItem item) -> item.name))
					.map(item -> itemSummary(item))
					.collect(Collectors.toList());
				long confirmedValue = items.stream().mapToLong(item -> item.confirmedValue).sum();
				return new DailySummary.LootSummary(entry.getKey(), source.drops, source.totalValue,
					confirmedValue, items, hiddenItems);
			})
			.sorted(Comparator.comparingLong((DailySummary.LootSummary source) -> source.value).reversed())
			.collect(Collectors.toList());
	}

	private DailySummary.ItemSummary itemSummary(TrackerData.LootItem item)
	{
		long confirmedValue = item.confirmedValueOverride == null ? item.confirmedValue : item.confirmedValueOverride;
		return new DailySummary.ItemSummary(item.itemId, item.name, item.quantity, item.totalValue,
			item.confirmedQuantity, confirmedValue, item.geConfirmedQuantity, item.geConfirmedValue,
			item.alchConfirmedQuantity, item.alchConfirmedValue, item.kept, item.confirmedValueOverride);
	}

	private static final class RaidAccumulator
	{
		int completions;
		long personalPoints;
		int pointRecords;
		long lootPoints;
		long teamPoints;
		int teamPointRecords;
		Integer minimumRaidLevel;
		Integer maximumRaidLevel;
	}

}

package com.pvmtracker;

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

final class GeSaleMatcher
{
	enum ConfirmationMethod
	{
		GRAND_EXCHANGE,
		HIGH_ALCHEMY
	}

	private GeSaleMatcher()
	{
	}

	static MatchResult match(TrackerData data, int itemId, int soldQuantity, long proceeds)
	{
		return match(data, itemId, soldQuantity, proceeds, ConfirmationMethod.GRAND_EXCHANGE);
	}

	static MatchResult match(TrackerData data, int itemId, int confirmedQuantity, long proceeds,
		ConfirmationMethod method)
	{
		if (confirmedQuantity <= 0 || proceeds <= 0)
		{
			return new MatchResult(0, 0);
		}

		if (method == ConfirmationMethod.GRAND_EXCHANGE)
		{
			proceeds = GrandExchangeTax.netProceeds(confirmedQuantity, proceeds);
		}

		List<Lot> lots = new ArrayList<>();
		data.lootDays.entrySet().stream()
			.sorted(Map.Entry.comparingByKey())
			.forEach(day -> day.getValue().sources.entrySet().stream()
				.sorted(Map.Entry.comparingByKey())
				.forEach(source ->
				{
					TrackerData.LootItem item = source.getValue().items.get(itemId);
					if (item != null && item.quantity > item.confirmedQuantity)
					{
						lots.add(new Lot(day.getKey(), source.getKey(), item));
					}
				}));

		long available = lots.stream().mapToLong(lot -> lot.item.quantity - lot.item.confirmedQuantity).sum();
		long matchedQuantity = Math.min(available, confirmedQuantity);
		if (matchedQuantity <= 0)
		{
			return new MatchResult(0, 0);
		}
		long matchedProceeds = prorate(proceeds, matchedQuantity, confirmedQuantity);
		long remainingQuantity = matchedQuantity;
		long remainingProceeds = matchedProceeds;
		for (Lot lot : lots)
		{
			long take = Math.min(remainingQuantity, lot.item.quantity - lot.item.confirmedQuantity);
			if (take <= 0)
			{
				continue;
			}
			long allocation = take == remainingQuantity
				? remainingProceeds : prorate(matchedProceeds, take, matchedQuantity);
			lot.item.confirmedQuantity += take;
			lot.item.confirmedValue += allocation;
			matchKillLog(data, lot.date, lot.source, itemId, take, allocation);
			if (method == ConfirmationMethod.HIGH_ALCHEMY)
			{
				lot.item.alchConfirmedQuantity += take;
				lot.item.alchConfirmedValue += allocation;
			}
			else
			{
				lot.item.geConfirmedQuantity += take;
				lot.item.geConfirmedValue += allocation;
			}
			remainingQuantity -= take;
			remainingProceeds -= allocation;
			if (remainingQuantity == 0)
			{
				break;
			}
		}
		return new MatchResult(matchedQuantity, matchedProceeds);
	}

	private static void matchKillLog(TrackerData data, String date, String source, int itemId,
		long quantity, long proceeds)
	{
		long remainingQuantity = quantity;
		long remainingProceeds = proceeds;
		for (TrackerData.KillLogEntry kill : data.killLog)
		{
			if (remainingQuantity == 0 || !date.equals(kill.date) || !source.equals(kill.source))
			{
				continue;
			}
			for (TrackerData.KillLootItem item : kill.items)
			{
				if (item.itemId != itemId || item.quantity <= item.confirmedQuantity)
				{
					continue;
				}
				long take = Math.min(remainingQuantity, item.quantity - item.confirmedQuantity);
				long allocation = take == remainingQuantity
					? remainingProceeds : prorate(proceeds, take, quantity);
				item.confirmedQuantity += take;
				item.confirmedValue += allocation;
				remainingQuantity -= take;
				remainingProceeds -= allocation;
				if (remainingQuantity == 0)
				{
					return;
				}
			}
		}
	}

	private static long prorate(long value, long numerator, long denominator)
	{
		return BigInteger.valueOf(value).multiply(BigInteger.valueOf(numerator))
			.divide(BigInteger.valueOf(denominator)).longValueExact();
	}

	static final class MatchResult
	{
		final long quantity;
		final long value;

		private MatchResult(long quantity, long value)
		{
			this.quantity = quantity;
			this.value = value;
		}
	}

	private static final class Lot
	{
		private final String date;
		private final String source;
		private final TrackerData.LootItem item;

		private Lot(String date, String source, TrackerData.LootItem item)
		{
			this.date = date;
			this.source = source;
			this.item = item;
		}
	}
}

package com.pvmtracker;

final class GrandExchangeTax
{
	private static final long TAX_DIVISOR = 50L;
	private static final long MAX_TAX_PER_ITEM = 5_000_000L;

	private GrandExchangeTax()
	{
	}

	static long netProceeds(long quantity, long grossProceeds)
	{
		if (quantity <= 0 || grossProceeds <= 0)
		{
			return grossProceeds;
		}

		long unitPrice = grossProceeds / quantity;
		long higherPriceQuantity = grossProceeds % quantity;
		long lowerPriceQuantity = quantity - higherPriceQuantity;
		long tax = lowerPriceQuantity * taxPerItem(unitPrice)
			+ higherPriceQuantity * taxPerItem(unitPrice + 1L);
		return grossProceeds - tax;
	}

	private static long taxPerItem(long price)
	{
		return Math.min(price / TAX_DIVISOR, MAX_TAX_PER_ITEM);
	}
}

package com.pvmtracker;

final class HighAlchTracker
{
	private Pending pending;

	void begin(int itemId, long itemQuantity, long coinQuantity, int highAlchPrice, int tick)
	{
		pending = itemId < 0 || itemQuantity <= 0 || highAlchPrice <= 0
			? null : new Pending(itemId, itemQuantity, coinQuantity, highAlchPrice, tick);
	}

	Confirmation observe(int itemId, long itemQuantity, long coinQuantity, int tick)
	{
		Pending current = pending;
		if (current == null)
		{
			return null;
		}
		if (tick - current.tick > 2)
		{
			pending = null;
			return null;
		}
		if (itemId != current.itemId || itemQuantity >= current.itemQuantity
			|| coinQuantity - current.coinQuantity != current.highAlchPrice)
		{
			return null;
		}
		pending = null;
		return new Confirmation(current.itemId, current.highAlchPrice);
	}

	int pendingItemId()
	{
		return pending == null ? -1 : pending.itemId;
	}

	void clear()
	{
		pending = null;
	}

	static final class Confirmation
	{
		final int itemId;
		final long value;

		private Confirmation(int itemId, long value)
		{
			this.itemId = itemId;
			this.value = value;
		}
	}

	private static final class Pending
	{
		private final int itemId;
		private final long itemQuantity;
		private final long coinQuantity;
		private final int highAlchPrice;
		private final int tick;

		private Pending(int itemId, long itemQuantity, long coinQuantity, int highAlchPrice, int tick)
		{
			this.itemId = itemId;
			this.itemQuantity = itemQuantity;
			this.coinQuantity = coinQuantity;
			this.highAlchPrice = highAlchPrice;
			this.tick = tick;
		}
	}
}

