package com.pvmtracker;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class KillCountMessageParser
{
	private static final Pattern KILLCOUNT_PATTERN = Pattern.compile(
		"Your (?<pre>completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?(?<boss>.+?)(?:</col>)? "
			+ "(?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?)is: ?"
			+ "<col=[0-9a-f]{6}>(?<kc>[0-9,]+)</col>");

	private KillCountMessageParser()
	{
	}

	static Observation parse(String message)
	{
		Matcher matcher = KILLCOUNT_PATTERN.matcher(message);
		if (!matcher.find())
		{
			return null;
		}
		String pre = matcher.group("pre");
		String post = matcher.group("post");
		if ((pre == null || pre.isEmpty()) && (post == null || post.isEmpty()))
		{
			return null;
		}
		String source = BossRegistry.canonicalize(matcher.group("boss"));
		if (source == null)
		{
			return null;
		}
		int killCount = Integer.parseInt(matcher.group("kc").replace(",", ""));
		return new Observation(source, killCount);
	}

	static final class Observation
	{
		final String source;
		final int killCount;

		private Observation(String source, int killCount)
		{
			this.source = source;
			this.killCount = killCount;
		}
	}
}

package com.pvmtracker;

import java.time.LocalDate;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;

final class KillCountService
{
	boolean recordCompletion(TrackerData data, LocalDate date, String boss, Integer exactKillCount)
	{
		Integer previous = data.lastKnownKillCounts.get(boss);
		int delta;
		int ending;
		if (exactKillCount == null)
		{
			delta = 1;
			ending = previous == null ? -1 : previous + 1;
		}
		else
		{
			if (previous != null && exactKillCount < previous)
			{
				correctAheadCount(data, date, boss, previous - exactKillCount, exactKillCount);
				return true;
			}
			if (previous != null && exactKillCount.equals(previous))
			{
				return false;
			}
			// An exact KC message proves that this completion happened, but a jump in the
			// absolute count does not prove that the plugin observed the intervening kills.
			delta = 1;
			ending = exactKillCount;
		}

		TrackerData.KcDay day = data.kcDays.computeIfAbsent(date.toString(), ignored -> new TrackerData.KcDay());
		day.kills.merge(boss, delta, Integer::sum);
		if (previous != null)
		{
			day.startingKillCounts.putIfAbsent(boss, previous);
		}
		else if (exactKillCount != null)
		{
			day.startingKillCounts.putIfAbsent(boss, Math.max(0, exactKillCount - delta));
		}
		if (ending >= 0)
		{
			day.endingKillCounts.put(boss, ending);
			data.lastKnownKillCounts.put(boss, ending);
		}
		data.lastKnownKillCountsAt = date.toString();
		return true;
	}

	private void correctAheadCount(TrackerData data, LocalDate date, String boss, int correction, int exactKillCount)
	{
		TrackerData.KcDay day = data.kcDays.get(date.toString());
		if (day != null)
		{
			Integer starting = day.startingKillCounts.get(boss);
			Integer ending = day.endingKillCounts.get(boss);
			if (starting != null)
			{
				day.startingKillCounts.put(boss, Math.max(0, starting - correction));
			}
			if (ending != null)
			{
				day.endingKillCounts.put(boss, Math.max(0, ending - correction));
			}
		}
		data.lastKnownKillCounts.put(boss, exactKillCount);
		data.lastKnownKillCountsAt = date.toString();
	}

	boolean recordLootCompletionIfMissing(TrackerData data, LocalDate date, String boss, int lootDrops)
	{
		TrackerData.KcDay day = data.kcDays.get(date.toString());
		int recordedKills = day == null ? 0 : day.kills.getOrDefault(boss, 0);
		if (recordedKills >= lootDrops)
		{
			return false;
		}
		return recordCompletion(data, date, boss, null);
	}

	int reconcile(TrackerData data, LocalDate date, Map<String, Integer> hiscoreCounts)
	{
		if (data.lastKnownKillCounts.isEmpty())
		{
			data.lastKnownKillCounts.putAll(hiscoreCounts);
			data.lastKnownKillCountsAt = date.toString();
			return 0;
		}

		LocalDate baselineDate = data.lastKnownKillCountsAt == null
			? date : LocalDate.parse(data.lastKnownKillCountsAt);
		int synchronizedKills = 0;
		for (Map.Entry<String, Integer> entry : hiscoreCounts.entrySet())
		{
			String boss = entry.getKey();
			int remote = entry.getValue();
			Integer local = data.lastKnownKillCounts.get(boss);
			if (local == null)
			{
				data.lastKnownKillCounts.put(boss, remote);
				continue;
			}
			if (remote < local)
			{
				if (canCorrectSingleCountDrift(data, baselineDate, boss, local, remote))
				{
					correctAheadCount(data, baselineDate, boss, 1, remote);
				}
				continue;
			}
			if (remote == local)
			{
				continue;
			}

			int delta = remote - local;
			data.lastKnownKillCounts.put(boss, remote);
			synchronizedKills += delta;
		}
		data.lastKnownKillCountsAt = date.toString();
		return synchronizedKills;
	}

	boolean repairLegacyLootKillCounts(TrackerData data)
	{
		Set<String> sources = new LinkedHashSet<>(data.lastKnownKillCounts.keySet());
		for (TrackerData.KillLogEntry kill : data.killLog)
		{
			if (kill.source != null)
			{
				sources.add(kill.source);
			}
		}

		boolean changed = false;
		for (String source : sources)
		{
			changed |= repairLegacyLootKillCounts(data, source);
		}
		return changed;
	}

	private boolean repairLegacyLootKillCounts(TrackerData data, String source)
	{
		Integer anchorCount = null;
		int anchorIndex = -1;
		boolean changed = false;

		for (int i = 0; i < data.killLog.size(); i++)
		{
			TrackerData.KillLogEntry kill = data.killLog.get(i);
			if (!source.equals(kill.source) || kill.lootCaptured != null || kill.killCount == null)
			{
				continue;
			}
			if (anchorCount != null)
			{
				changed |= fillProvenSequence(data, source, anchorIndex + 1, i + 1,
					anchorCount, kill.killCount);
			}
			anchorCount = kill.killCount;
			anchorIndex = i;
		}

		Integer latestKnown = data.lastKnownKillCounts.get(source);
		if (anchorCount != null && latestKnown != null && latestKnown >= anchorCount)
		{
			changed |= fillProvenSequence(data, source, anchorIndex + 1, data.killLog.size(),
				anchorCount, latestKnown);
		}
		return changed;
	}

	private boolean fillProvenSequence(TrackerData data, String source, int fromIndex, int toIndex,
		int startingCount, int endingCount)
	{
		int observedKills = 0;
		for (int i = fromIndex; i < toIndex; i++)
		{
			TrackerData.KillLogEntry kill = data.killLog.get(i);
			if (source.equals(kill.source) && kill.lootCaptured == null)
			{
				observedKills += Math.max(1, kill.kills);
			}
		}
		if (endingCount - startingCount != observedKills)
		{
			return false;
		}

		boolean changed = false;
		int count = startingCount;
		for (int i = fromIndex; i < toIndex; i++)
		{
			TrackerData.KillLogEntry kill = data.killLog.get(i);
			if (!source.equals(kill.source) || kill.lootCaptured != null)
			{
				continue;
			}
			count += Math.max(1, kill.kills);
			if (kill.killCount == null)
			{
				kill.killCount = count;
				changed = true;
			}
		}
		return changed;
	}

	private boolean canCorrectSingleCountDrift(TrackerData data, LocalDate date, String boss, int local, int remote)
	{
		if (local - remote != 1)
		{
			return false;
		}
		TrackerData.KcDay day = data.kcDays.get(date.toString());
		if (day == null)
		{
			return false;
		}
		Integer start = day.startingKillCounts.get(boss);
		Integer end = day.endingKillCounts.get(boss);
		int recorded = day.kills.getOrDefault(boss, 0);
		return start != null && end != null && end == local && recorded == end - start;
	}
}

package com.pvmtracker;

import java.time.Duration;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.UUID;

final class KillLogService
{
	private static final Duration LOOT_BEFORE_COMPLETION_WINDOW = Duration.ofSeconds(90);

	boolean recordCompletion(TrackerData data, String date, String occurredAt, String source, int killCount)
	{
		for (int i = data.killLog.size() - 1; i >= 0; i--)
		{
			TrackerData.KillLogEntry kill = data.killLog.get(i);
			if (RaidLootMatcher.matchesCompletion(kill.source, source)
				&& Integer.valueOf(killCount).equals(kill.killCount))
			{
				return false;
			}
		}

		for (int i = data.killLog.size() - 1; i >= 0; i--)
		{
			TrackerData.KillLogEntry kill = data.killLog.get(i);
			if (kill.killCount == null && kill.hasCapturedLoot()
				&& RaidLootMatcher.matchesCompletion(kill.source, source)
				&& withinReverseOrderWindow(kill.occurredAt, occurredAt))
			{
				kill.killCount = killCount;
				return true;
			}
		}

		TrackerData.KillLogEntry kill = new TrackerData.KillLogEntry();
		kill.id = UUID.randomUUID().toString();
		kill.date = date;
		kill.occurredAt = occurredAt;
		kill.source = source;
		kill.killCount = killCount;
		kill.lootCaptured = false;
		data.killLog.add(kill);
		return true;
	}

	TrackerData.KillLogEntry claimOldestUnlootedCompletion(TrackerData data, String lootSource)
	{
		for (TrackerData.KillLogEntry kill : data.killLog)
		{
			if (!kill.hasCapturedLoot() && kill.killCount != null
				&& RaidLootMatcher.matchesCompletion(lootSource, kill.source))
			{
				kill.lootCaptured = true;
				return kill;
			}
		}
		return null;
	}

	TrackerData.KillLogEntry findCompletion(TrackerData data, String source, int killCount)
	{
		for (int i = data.killLog.size() - 1; i >= 0; i--)
		{
			TrackerData.KillLogEntry kill = data.killLog.get(i);
			if (RaidLootMatcher.matchesCompletion(kill.source, source)
				&& Integer.valueOf(killCount).equals(kill.killCount))
			{
				return kill;
			}
		}
		return null;
	}

	boolean linkRaidCompletions(TrackerData data)
	{
		boolean changed = false;
		for (TrackerData.RaidCompletion raid : data.raidCompletions)
		{
			if (raid.killId != null || raid.source == null || raid.killCount == null)
			{
				continue;
			}
			TrackerData.KillLogEntry kill = findCompletion(data, raid.source, raid.killCount);
			if (kill != null)
			{
				raid.killId = kill.id;
				changed = true;
			}
		}
		return changed;
	}

	TrackerData.KillLogEntry createLootOnly(String date, String occurredAt, String source,
		Integer killCount, int kills)
	{
		TrackerData.KillLogEntry kill = new TrackerData.KillLogEntry();
		kill.id = UUID.randomUUID().toString();
		kill.date = date;
		kill.occurredAt = occurredAt;
		kill.source = source;
		kill.killCount = killCount;
		kill.kills = kills;
		kill.lootCaptured = true;
		return kill;
	}

	private boolean withinReverseOrderWindow(String lootOccurredAt, String completionOccurredAt)
	{
		if (lootOccurredAt == null || completionOccurredAt == null)
		{
			return false;
		}
		try
		{
			return Duration.between(Instant.parse(lootOccurredAt), Instant.parse(completionOccurredAt)).abs()
				.compareTo(LOOT_BEFORE_COMPLETION_WINDOW) <= 0;
		}
		catch (DateTimeParseException ignored)
		{
			return false;
		}
	}
}

package com.pvmtracker;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

final class LootTransformationService
{
	private LootTransformationService()
	{
	}

	static boolean isSupported(String source)
	{
		return source != null && source.toLowerCase(java.util.Locale.ENGLISH).startsWith("tarnished ");
	}

	static boolean replace(TrackerData data, String intermediateName, List<ReplacementItem> replacements)
	{
		List<Lot> lots = new ArrayList<>();
		data.lootDays.entrySet().stream().sorted(Map.Entry.comparingByKey()).forEach(day ->
		{
			day.getValue().sources.entrySet().stream().sorted(Map.Entry.comparingByKey()).forEach(source ->
			{
				source.getValue().items.values().stream()
					.filter(item -> intermediateName.equalsIgnoreCase(item.name) && item.quantity > item.confirmedQuantity)
					.forEach(item -> lots.add(new Lot(day.getKey(), source.getKey(), source.getValue(), item)));
			});
		});

		boolean changed = false;
		int lotIndex = 0;
		for (ReplacementItem replacement : replacements)
		{
			long remaining = replacement.quantity;
			long unitValue = replacement.quantity == 0 ? 0 : replacement.totalValue / replacement.quantity;
			while (remaining > 0 && lotIndex < lots.size())
			{
				Lot lot = lots.get(lotIndex);
				long available = lot.intermediate.quantity - lot.intermediate.confirmedQuantity;
				if (available <= 0)
				{
					lotIndex++;
					continue;
				}
				long take = Math.min(remaining, available);
				long oldUnitValue = lot.intermediate.quantity == 0 ? 0
					: lot.intermediate.totalValue / lot.intermediate.quantity;
				long oldValue = oldUnitValue * take;
				long newValue = unitValue * take;
				lot.intermediate.quantity -= take;
				lot.intermediate.totalValue -= oldValue;
				TrackerData.LootItem revealed = lot.source.items.computeIfAbsent(replacement.itemId,
					ignored -> new TrackerData.LootItem(replacement.itemId, replacement.name));
				revealed.quantity += take;
				revealed.totalValue += newValue;
				replaceKillLogItems(data, lot.date, lot.sourceName, intermediateName,
					replacement, take, unitValue);
				lot.source.totalValue += newValue - oldValue;
				if (lot.intermediate.quantity == 0 && lot.intermediate.confirmedQuantity == 0)
				{
					lot.source.items.remove(lot.intermediate.itemId);
					lotIndex++;
				}
				remaining -= take;
				changed = true;
			}
		}
		if (changed)
		{
			TrackerDataEditor.recalculateAllSourceTotals(data);
		}
		return changed;
	}

	private static void replaceKillLogItems(TrackerData data, String date, String sourceName,
		String intermediateName, ReplacementItem replacement, long quantity, long replacementUnitValue)
	{
		long remaining = quantity;
		for (TrackerData.KillLogEntry kill : data.killLog)
		{
			if (remaining == 0 || !date.equals(kill.date) || !sourceName.equals(kill.source))
			{
				continue;
			}
			for (int i = 0; i < kill.items.size() && remaining > 0; i++)
			{
				TrackerData.KillLootItem intermediate = kill.items.get(i);
				if (!intermediateName.equalsIgnoreCase(intermediate.name) || intermediate.quantity <= 0)
				{
					continue;
				}
				long take = Math.min(remaining, intermediate.quantity);
				long oldUnitValue = intermediate.totalValue / intermediate.quantity;
				intermediate.quantity -= take;
				intermediate.totalValue -= oldUnitValue * take;
				if (intermediate.quantity == 0)
				{
					kill.items.remove(i--);
				}
				TrackerData.KillLootItem revealed = kill.items.stream()
					.filter(item -> item.itemId == replacement.itemId)
					.findFirst()
					.orElseGet(() ->
					{
						TrackerData.KillLootItem item = new TrackerData.KillLootItem(
							replacement.itemId, replacement.name, 0, 0);
						kill.items.add(item);
						return item;
					});
				revealed.quantity += take;
				revealed.totalValue += replacementUnitValue * take;
				remaining -= take;
			}
		}
	}

	static final class ReplacementItem
	{
		final int itemId;
		final String name;
		final long quantity;
		final long totalValue;

		ReplacementItem(int itemId, String name, long quantity, long totalValue)
		{
			this.itemId = itemId;
			this.name = name;
			this.quantity = quantity;
			this.totalValue = totalValue;
		}
	}

	private static final class Lot
	{
		private final String date;
		private final String sourceName;
		private final TrackerData.LootSource source;
		private final TrackerData.LootItem intermediate;

		private Lot(String date, String sourceName, TrackerData.LootSource source,
			TrackerData.LootItem intermediate)
		{
			this.date = date;
			this.sourceName = sourceName;
			this.source = source;
			this.intermediate = intermediate;
		}
	}
}

package com.pvmtracker;

import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;

final class LootValueBackfill
{
	private LootValueBackfill()
	{
	}

	static Set<Integer> missingItemIds(TrackerData data)
	{
		Set<Integer> ids = new LinkedHashSet<>();
		for (TrackerData.LootDay day : data.lootDays.values())
		{
			for (TrackerData.LootSource source : day.sources.values())
			{
				for (TrackerData.LootItem item : source.items.values())
				{
					if (item.quantity > 0 && item.totalValue == 0)
					{
						ids.add(item.itemId);
					}
				}
			}
		}
		return ids;
	}

	static boolean apply(TrackerData data, Map<Integer, Long> unitValues)
	{
		boolean changed = false;
		for (TrackerData.LootDay day : data.lootDays.values())
		{
			for (TrackerData.LootSource source : day.sources.values())
			{
				for (TrackerData.LootItem item : source.items.values())
				{
					long unitValue = unitValues.getOrDefault(item.itemId, 0L);
					if (item.quantity > 0 && item.totalValue == 0 && unitValue > 0)
					{
						item.totalValue = unitValue * item.quantity;
						changed = true;
					}
				}
			}
		}
		if (changed)
		{
			TrackerDataEditor.recalculateAllSourceTotals(data);
		}
		return changed;
	}
}

package com.pvmtracker;

import com.google.gson.Gson;
import java.io.IOException;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

@Slf4j
final class PvmHubUploader
{
	static final String UPLOAD_URL = "https://osrs.pvm-hub.com/api/profiles";
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	private PvmHubUploader()
	{
	}

	interface UploadCallback
	{
		void onComplete(Call call, boolean successful, int responseCode);
	}

	static Call uploadSnapshot(TrackerData snapshot, Gson gson, OkHttpClient httpClient,
		UploadCallback callback)
	{
		String json = gson.toJson(snapshot);
		Request request = new Request.Builder()
			.url(UPLOAD_URL)
			.post(RequestBody.create(JSON, json))
			.build();
		Call call = httpClient.newCall(request);
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call failedCall, IOException ex)
			{
				log.debug("PvM Hub upload failed", ex);
				callback.onComplete(failedCall, false, -1);
			}

			@Override
			public void onResponse(Call completedCall, Response response)
			{
				try
				{
					if (!response.isSuccessful())
					{
						String details = "";
						try
						{
							if (response.body() != null)
							{
								details = response.body().string().replaceAll("\\s+", " ").trim();
								if (details.length() > 2_000)
								{
									details = details.substring(0, 2_000) + "…";
								}
							}
						}
						catch (IOException ex)
						{
							log.debug("Unable to read PvM Hub error response", ex);
						}
						if (details.isEmpty())
						{
							log.debug("PvM Hub upload returned HTTP {}", response.code());
						}
						else
						{
							log.debug("PvM Hub upload returned HTTP {}: {}", response.code(), details);
						}
					}
					callback.onComplete(completedCall, response.isSuccessful(), response.code());
				}
				finally
				{
					response.close();
				}
			}
		});
		return call;
	}
}

package com.pvmtracker;

import java.time.Duration;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.List;
import net.runelite.api.gameval.ItemID;

final class RaidLootMatcher
{
	private static final Duration COMPLETION_ATTRIBUTION_WINDOW = Duration.ofMinutes(2);

	private RaidLootMatcher()
	{
	}

	static boolean isRaid(String source)
	{
		return source != null && (source.startsWith("Chambers of Xeric")
			|| source.startsWith("Theatre of Blood")
			|| source.startsWith("Tombs of Amascut"));
	}

	static boolean isGenericRaidSource(String source)
	{
		return "Chambers of Xeric".equals(source)
			|| "Theatre of Blood".equals(source)
			|| "Tombs of Amascut".equals(source);
	}

	static boolean isNonRewardLoot(String source, int itemCount, int onlyItemId)
	{
		return source != null && source.startsWith("Theatre of Blood")
			&& itemCount == 1 && onlyItemId == ItemID.TOB_BOOK_VERZIK;
	}

	static boolean matchesCompletion(String lootSource, String completionSource)
	{
		if (lootSource == null || completionSource == null)
		{
			return false;
		}
		if (lootSource.equals(completionSource))
		{
			return true;
		}
		return sameRaid(lootSource, completionSource, "Chambers of Xeric")
			|| sameRaid(lootSource, completionSource, "Theatre of Blood")
			|| sameRaid(lootSource, completionSource, "Tombs of Amascut");
	}

	static String resolveSource(String lootSource, String lootOccurredAt,
		List<TrackerData.RaidCompletion> completions)
	{
		if (!isGenericRaidSource(lootSource) || lootOccurredAt == null)
		{
			return lootSource;
		}
		try
		{
			Instant lootTime = Instant.parse(lootOccurredAt);
			TrackerData.RaidCompletion closest = null;
			Duration closestDistance = null;
			for (TrackerData.RaidCompletion completion : completions)
			{
				if (completion == null || completion.source == null || completion.occurredAt == null
					|| lootSource.equals(completion.source)
					|| !matchesCompletion(lootSource, completion.source))
				{
					continue;
				}
				Duration distance = Duration.between(Instant.parse(completion.occurredAt), lootTime).abs();
				if (distance.compareTo(COMPLETION_ATTRIBUTION_WINDOW) <= 0
					&& (closestDistance == null || distance.compareTo(closestDistance) < 0))
				{
					closest = completion;
					closestDistance = distance;
				}
			}
			return closest == null ? lootSource : closest.source;
		}
		catch (DateTimeParseException ignored)
		{
			return lootSource;
		}
	}

	static boolean repairGenericRaidLootAttribution(TrackerData data)
	{
		boolean changed = false;
		for (TrackerData.KillLogEntry kill : data.killLog)
		{
			String resolvedSource = resolveSource(kill.source, kill.occurredAt, data.raidCompletions);
			if (resolvedSource.equals(kill.source) || !canMoveUnmodifiedLoot(data, kill))
			{
				continue;
			}
			String originalSource = kill.source;
			moveLootAggregate(data, kill, resolvedSource);
			repairInferredKillCount(data, kill, originalSource);
			kill.source = resolvedSource;
			changed = true;
		}
		return changed;
	}

	private static boolean canMoveUnmodifiedLoot(TrackerData data, TrackerData.KillLogEntry kill)
	{
		TrackerData.LootDay day = data.lootDays.get(kill.date);
		TrackerData.LootSource source = day == null ? null : day.sources.get(kill.source);
		if (source == null || source.drops < kill.kills)
		{
			return false;
		}
		for (TrackerData.KillLootItem killItem : kill.items)
		{
			TrackerData.LootItem item = source.items.get(killItem.itemId);
			if (item == null || item.quantity < killItem.quantity || item.totalValue < killItem.totalValue
				|| item.confirmedQuantity != 0 || item.confirmedValue != 0 || item.geConfirmedQuantity != 0
				|| item.geConfirmedValue != 0 || item.alchConfirmedQuantity != 0 || item.alchConfirmedValue != 0
				|| item.kept || item.confirmedValueOverride != null)
			{
				return false;
			}
		}
		return true;
	}

	private static void moveLootAggregate(TrackerData data, TrackerData.KillLogEntry kill, String resolvedSource)
	{
		TrackerData.LootDay day = data.lootDays.get(kill.date);
		TrackerData.LootSource original = day.sources.get(kill.source);
		TrackerData.LootSource target = day.sources.computeIfAbsent(resolvedSource,
			ignored -> new TrackerData.LootSource());
		original.drops -= kill.kills;
		target.drops += kill.kills;
		for (TrackerData.KillLootItem killItem : kill.items)
		{
			TrackerData.LootItem originalItem = original.items.get(killItem.itemId);
			originalItem.quantity -= killItem.quantity;
			originalItem.totalValue -= killItem.totalValue;
			if (originalItem.quantity == 0 && originalItem.totalValue == 0)
			{
				original.items.remove(killItem.itemId);
			}
			TrackerData.LootItem targetItem = target.items.computeIfAbsent(killItem.itemId,
				ignored -> new TrackerData.LootItem(killItem.itemId, killItem.name));
			targetItem.quantity += killItem.quantity;
			targetItem.totalValue += killItem.totalValue;
		}
		if (original.drops == 0 && original.items.isEmpty())
		{
			day.sources.remove(kill.source);
		}
	}

	private static void repairInferredKillCount(TrackerData data, TrackerData.KillLogEntry kill,
		String originalSource)
	{
		if (kill.killCount != null)
		{
			return;
		}
		TrackerData.KcDay day = data.kcDays.get(kill.date);
		if (day == null)
		{
			return;
		}
		int recorded = day.kills.getOrDefault(originalSource, 0);
		int recovered = day.recoveredKills.getOrDefault(originalSource, 0);
		if (recorded - recovered < kill.kills)
		{
			return;
		}
		int correctedKills = recorded - kill.kills;
		if (correctedKills == 0)
		{
			day.kills.remove(originalSource);
		}
		else
		{
			day.kills.put(originalSource, correctedKills);
		}
		Integer ending = day.endingKillCounts.get(originalSource);
		if (ending != null)
		{
			int correctedEnding = Math.max(0, ending - kill.kills);
			day.endingKillCounts.put(originalSource, correctedEnding);
			if (ending.equals(data.lastKnownKillCounts.get(originalSource)))
			{
				data.lastKnownKillCounts.put(originalSource, correctedEnding);
			}
		}
	}

	private static boolean sameRaid(String first, String second, String raid)
	{
		return first.startsWith(raid) && second.startsWith(raid);
	}
}

package com.pvmtracker;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import java.util.List;

final class TrackerData
{
	int schemaVersion = 5;
	String lastKnownName = "";
	String lastKnownKillCountsAt;
	Map<String, Integer> lastKnownKillCounts = new LinkedHashMap<>();
	Map<String, KcDay> kcDays = new LinkedHashMap<>();
	Map<String, LootDay> lootDays = new LinkedHashMap<>();
	Map<String, Set<Integer>> hiddenLootItems = new LinkedHashMap<>();
	List<KillLogEntry> killLog = new ArrayList<>();
	List<RaidCompletion> raidCompletions = new ArrayList<>();
	Map<Integer, GeOffer> geOffers = new LinkedHashMap<>();

	boolean isLootHidden(String source, int itemId)
	{
		Set<Integer> hidden = hiddenLootItems.get(source);
		return hidden != null && hidden.contains(itemId);
	}

	Set<Integer> hiddenLootFor(String source)
	{
		return hiddenLootItems.computeIfAbsent(source, ignored -> new LinkedHashSet<>());
	}

	static final class KcDay
	{
		String intervalEnd;
		Map<String, Integer> kills = new LinkedHashMap<>();
		Map<String, Integer> recoveredKills = new LinkedHashMap<>();
		Map<String, Integer> startingKillCounts = new LinkedHashMap<>();
		Map<String, Integer> endingKillCounts = new LinkedHashMap<>();
	}

	static final class LootDay
	{
		Map<String, LootSource> sources = new LinkedHashMap<>();
		Map<String, Long> manualAdjustments = new LinkedHashMap<>();

	}

	static final class LootSource
	{
		int drops;
		long totalValue;
		Map<Integer, LootItem> items = new LinkedHashMap<>();

	}

	static final class LootItem
	{
		int itemId;
		String name;
		long quantity;
		long totalValue;
		long confirmedQuantity;
		long confirmedValue;
		long geConfirmedQuantity;
		long geConfirmedValue;
		long alchConfirmedQuantity;
		long alchConfirmedValue;
		boolean kept;
		Long confirmedValueOverride;

		LootItem()
		{
		}

		LootItem(int itemId, String name)
		{
			this.itemId = itemId;
			this.name = name;
		}
	}

	static final class GeOffer
	{
		int itemId;
		int totalQuantity;
		int price;
		int quantitySold;
		int spent;
		String state;

		GeOffer()
		{
		}

		GeOffer(int itemId, int totalQuantity, int price, int quantitySold, int spent, String state)
		{
			this.itemId = itemId;
			this.totalQuantity = totalQuantity;
			this.price = price;
			this.quantitySold = quantitySold;
			this.spent = spent;
			this.state = state;
		}
	}

	static final class KillLogEntry
	{
		String id;
		String date;
		String occurredAt;
		String source;
		Integer killCount;
		int kills = 1;
		Boolean lootCaptured;
		long totalValue;
		List<KillLootItem> items = new ArrayList<>();

		boolean hasCapturedLoot()
		{
			// Legacy kill-log rows were created only by loot events, so a missing
			// value means that loot was captured.
			return lootCaptured == null || lootCaptured;
		}
	}

	static final class KillLootItem
	{
		int itemId;
		String name;
		long quantity;
		long totalValue;
		long confirmedQuantity;
		long confirmedValue;

		KillLootItem()
		{
		}

		KillLootItem(int itemId, String name, long quantity, long totalValue)
		{
			this.itemId = itemId;
			this.name = name;
			this.quantity = quantity;
			this.totalValue = totalValue;
		}
	}

	static final class RaidCompletion
	{
		String id;
		String killId;
		String date;
		String occurredAt;
		String source;
		Integer killCount;
		Integer personalPoints;
		Integer lootPoints;
		Integer teamPoints;
		Integer raidLevel;
	}
}

package com.pvmtracker;

import java.time.LocalDate;

final class TrackerDataEditor
{
	private TrackerDataEditor()
	{
	}

	static boolean setSplit(TrackerData data, LocalDate date, String boss, long value)
	{
		String key = date.toString();
		TrackerData.LootDay day = data.lootDays.get(key);
		if (value == 0L)
		{
			if (day == null || day.manualAdjustments.remove(boss) == null)
			{
				return false;
			}
			removeEmptyDay(data, key, day);
			return true;
		}
		if (day == null)
		{
			day = new TrackerData.LootDay();
			data.lootDays.put(key, day);
		}
		Long previous = day.manualAdjustments.put(boss, value);
		return previous == null || previous != value;
	}

	static boolean deleteBossLoot(TrackerData data, LocalDate date, String boss)
	{
		String key = date.toString();
		TrackerData.LootDay day = data.lootDays.get(key);
		boolean changed = day != null && day.sources.remove(boss) != null;
		for (TrackerData.KillLogEntry kill : data.killLog)
		{
			if (key.equals(kill.date) && boss.equals(kill.source)
				&& (!kill.items.isEmpty() || kill.totalValue != 0))
			{
				kill.items.clear();
				kill.totalValue = 0;
				changed = true;
			}
		}
		if (day != null)
		{
			removeEmptyDay(data, key, day);
		}
		return changed;
	}

	static boolean deleteDayGp(TrackerData data, LocalDate date)
	{
		String key = date.toString();
		boolean changed = data.lootDays.remove(key) != null;
		for (TrackerData.KillLogEntry kill : data.killLog)
		{
			if (key.equals(kill.date) && (!kill.items.isEmpty() || kill.totalValue != 0))
			{
				kill.items.clear();
				kill.totalValue = 0;
				changed = true;
			}
		}
		return changed;
	}

	static boolean setLootHidden(TrackerData data, String boss, int itemId, boolean hidden)
	{
		boolean changed;
		if (hidden)
		{
			changed = data.hiddenLootFor(boss).add(itemId);
		}
		else
		{
			java.util.Set<Integer> hiddenItems = data.hiddenLootItems.get(boss);
			changed = hiddenItems != null && hiddenItems.remove(itemId);
			if (hiddenItems != null && hiddenItems.isEmpty())
			{
				data.hiddenLootItems.remove(boss);
			}
		}
		if (changed)
		{
			recalculateBossTotals(data, boss);
		}
		return changed;
	}

	static boolean setLootKept(TrackerData data, LocalDate date, String boss, int itemId, boolean kept)
	{
		TrackerData.LootDay day = data.lootDays.get(date.toString());
		TrackerData.LootSource source = day == null ? null : day.sources.get(boss);
		TrackerData.LootItem item = source == null ? null : source.items.get(itemId);
		if (item == null || item.kept == kept)
		{
			return false;
		}
		item.kept = kept;
		return true;
	}

	static boolean setConfirmedValueOverride(TrackerData data, LocalDate date, String boss, int itemId, Long value)
	{
		TrackerData.LootDay day = data.lootDays.get(date.toString());
		TrackerData.LootSource source = day == null ? null : day.sources.get(boss);
		TrackerData.LootItem item = source == null ? null : source.items.get(itemId);
		if (item == null || java.util.Objects.equals(item.confirmedValueOverride, value))
		{
			return false;
		}
		item.confirmedValueOverride = value;
		return true;
	}

	static void recalculateAllSourceTotals(TrackerData data)
	{
		for (TrackerData.LootDay day : data.lootDays.values())
		{
			for (java.util.Map.Entry<String, TrackerData.LootSource> entry : day.sources.entrySet())
			{
				recalculateSourceTotal(data, entry.getKey(), entry.getValue());
			}
		}
		recalculateKillLogTotals(data);
	}

	private static void recalculateBossTotals(TrackerData data, String boss)
	{
		for (TrackerData.LootDay day : data.lootDays.values())
		{
			TrackerData.LootSource source = day.sources.get(boss);
			if (source != null)
			{
				recalculateSourceTotal(data, boss, source);
			}
		}
		for (TrackerData.KillLogEntry kill : data.killLog)
		{
			if (boss.equals(kill.source))
			{
				kill.totalValue = kill.items.stream()
					.filter(item -> !data.isLootHidden(boss, item.itemId))
					.mapToLong(item -> item.totalValue).sum();
			}
		}
	}

	private static void recalculateKillLogTotals(TrackerData data)
	{
		for (TrackerData.KillLogEntry kill : data.killLog)
		{
			kill.totalValue = kill.items.stream()
				.filter(item -> !data.isLootHidden(kill.source, item.itemId))
				.mapToLong(item -> item.totalValue).sum();
		}
	}

	private static void recalculateSourceTotal(TrackerData data, String boss, TrackerData.LootSource source)
	{
		source.totalValue = source.items.values().stream()
			.filter(item -> !data.isLootHidden(boss, item.itemId))
			.mapToLong(item -> item.totalValue).sum();
	}

	private static void removeEmptyDay(TrackerData data, String key, TrackerData.LootDay day)
	{
		if (day.sources.isEmpty() && day.manualAdjustments.isEmpty())
		{
			data.lootDays.remove(key);
		}
	}
}

package com.pvmtracker;

import java.util.Map;

final class TrackerDataMigration
{
	private static final int RAID_KC_REPAIR_SCHEMA_VERSION = 4;
	private static final int OBSERVED_KC_ONLY_SCHEMA_VERSION = 5;

	private TrackerDataMigration()
	{
	}

	static boolean migrateToCurrentVersion(TrackerData data, int currentSchemaVersion)
	{
		if (data.schemaVersion >= currentSchemaVersion)
		{
			return false;
		}
		if (data.schemaVersion < RAID_KC_REPAIR_SCHEMA_VERSION)
		{
			repairInferredRaidKills(data);
		}
		if (data.schemaVersion < OBSERVED_KC_ONLY_SCHEMA_VERSION)
		{
			removeRecoveredKills(data);
		}
		data.schemaVersion = currentSchemaVersion;
		return true;
	}

	private static void removeRecoveredKills(TrackerData data)
	{
		for (TrackerData.KcDay day : data.kcDays.values())
		{
			for (Map.Entry<String, Integer> entry : new java.util.ArrayList<>(day.recoveredKills.entrySet()))
			{
				String source = entry.getKey();
				int observed = Math.max(0, day.kills.getOrDefault(source, 0) - entry.getValue());
				if (observed == 0)
				{
					day.kills.remove(source);
					day.startingKillCounts.remove(source);
					day.endingKillCounts.remove(source);
				}
				else
				{
					day.kills.put(source, observed);
					Integer ending = day.endingKillCounts.get(source);
					if (ending != null)
					{
						day.startingKillCounts.put(source, Math.max(0, ending - observed));
					}
				}
			}
			day.recoveredKills.clear();
			day.intervalEnd = null;
		}
	}

	private static void repairInferredRaidKills(TrackerData data)
	{
		for (Map.Entry<String, TrackerData.KcDay> dayEntry : data.kcDays.entrySet())
		{
			String date = dayEntry.getKey();
			TrackerData.KcDay day = dayEntry.getValue();
			for (Map.Entry<String, Integer> killEntry : new java.util.ArrayList<>(day.kills.entrySet()))
			{
				String source = killEntry.getKey();
				int recovered = day.recoveredKills.getOrDefault(source, 0);
				int observed = killEntry.getValue() - recovered;
				if (!RaidLootMatcher.isRaid(source) || recovered <= 0 || observed <= 0
					|| observed != exactLootCompletions(data, date, source))
				{
					continue;
				}
				day.kills.put(source, observed);
				day.recoveredKills.remove(source);
				Integer ending = day.endingKillCounts.get(source);
				if (ending != null)
				{
					day.startingKillCounts.put(source, Math.max(0, ending - observed));
				}
			}
		}
	}

	private static int exactLootCompletions(TrackerData data, String date, String source)
	{
		int count = 0;
		for (TrackerData.KillLogEntry kill : data.killLog)
		{
			if (date.equals(kill.date) && source.equals(kill.source) && kill.killCount != null)
			{
				count += kill.kills;
			}
		}
		return count;
	}
}

package com.pvmtracker;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import net.runelite.client.RuneLite;

final class TrackerStore
{
	private static final int PROFILE_ID_VERSION = 1;
	private static final int CURRENT_SCHEMA_VERSION = 5;
	private final Gson gson;
	private final Path directory;

	TrackerStore(Gson gson)
	{
		this(gson, RuneLite.RUNELITE_DIR.toPath().resolve("pvm-raid-daily-tracker"));
	}

	TrackerStore(Gson gson, Path directory)
	{
		this.gson = gson.newBuilder().setPrettyPrinting().create();
		this.directory = directory;
	}

	TrackerData load(long accountHash) throws IOException
	{
		Path file = fileFor(accountHash);
		if (!Files.exists(file))
		{
			return new TrackerData();
		}
		TrackerData data;
		try (Reader reader = Files.newBufferedReader(file))
		{
			data = gson.fromJson(reader, TrackerData.class);
		}
		if (data == null)
		{
			data = new TrackerData();
		}
		boolean migrated = TrackerDataMigration.migrateToCurrentVersion(data, CURRENT_SCHEMA_VERSION);
		TrackerDataEditor.recalculateAllSourceTotals(data);
		if (migrated)
		{
			writeAtomically(file, data);
		}
		return data;
	}

	void save(long accountHash, TrackerData data) throws IOException
	{
		Files.createDirectories(directory);
		Path destination = fileFor(accountHash);
		writeAtomically(destination, data);
	}

	void export(Path destination, TrackerData data) throws IOException
	{
		writeAtomically(destination, data);
	}

	private void writeAtomically(Path destination, TrackerData data) throws IOException
	{
		Path parent = destination.toAbsolutePath().getParent();
		if (parent == null)
		{
			throw new IOException("Export destination has no parent directory");
		}
		Files.createDirectories(parent);
		Path staging = Files.createTempFile(parent, destination.getFileName().toString(), ".new");
		try
		{
			try (Writer writer = Files.newBufferedWriter(staging))
			{
				gson.toJson(data, writer);
			}
			try
			{
				Files.move(staging, destination, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (AtomicMoveNotSupportedException ex)
			{
				Files.move(staging, destination, StandardCopyOption.REPLACE_EXISTING);
			}
		}
		finally
		{
			Files.deleteIfExists(staging);
		}
	}

	private Path fileFor(long accountHash)
	{
		return directory.resolve(Long.toUnsignedString(accountHash) + "-v" + PROFILE_ID_VERSION + ".json");
	}
}

package com.pvmtracker;

