package com.pvmtracker;

import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class DailySummaryServiceTest
{
	private final DailySummaryService summaryService = new DailySummaryService();
	private final KillCountService killCountService = new KillCountService();

	@Test
	public void buildsLocalKillTotalsAndMergesLootByDay()
	{
		TrackerData data = new TrackerData();
		data.lastKnownKillCounts.put("Vorkath", 100);
		data.lastKnownKillCounts.put("Tombs of Amascut", 20);
		LocalDate date = LocalDate.parse("2026-07-14");
		killCountService.recordCompletion(data, date, "Vorkath", 106);
		killCountService.recordCompletion(data, date, "Tombs of Amascut", 22);

		TrackerData.LootDay day = new TrackerData.LootDay();
		TrackerData.LootSource source = new TrackerData.LootSource();
		source.drops = 6;
		source.totalValue = 1_250_000;
		TrackerData.LootItem item = new TrackerData.LootItem(11286, "Draconic visage");
		item.quantity = 1;
		item.totalValue = 1_250_000;
		item.confirmedQuantity = 1;
		item.confirmedValue = 1_100_000;
		source.items.put(item.itemId, item);
		day.sources.put("Vorkath", source);
		day.manualAdjustments.put("Vorkath", 500_000L);
		data.lootDays.put(date.toString(), day);

		List<DailySummary> summaries = summaryService.build(data, LocalDate.parse("2026-07-15"), true);
		DailySummary completed = summaries.stream().filter(summary -> summary.date.equals(date))
			.findFirst().orElseThrow(AssertionError::new);

		assertEquals(2, completed.totalKills);
		assertEquals(Integer.valueOf(1), completed.kills.get("Vorkath"));
		assertEquals(Integer.valueOf(1), completed.kills.get("Tombs of Amascut"));
		assertEquals(1_250_000, completed.trackedLootValue);
		assertEquals(1_600_000, completed.confirmedValue);
		assertEquals(Integer.valueOf(100), completed.startingKillCounts.get("Vorkath"));
		assertEquals(Integer.valueOf(106), completed.endingKillCounts.get("Vorkath"));
	}

	@Test
	public void hiscoresAdvanceTheBaselineWithoutAddingTimelineKills()
	{
		TrackerData data = new TrackerData();
		data.lastKnownKillCounts.put("Zulrah", 10);
		data.lastKnownKillCountsAt = "2026-07-10";

		assertEquals(5, killCountService.reconcile(data, LocalDate.parse("2026-07-13"), counts("Zulrah", 15)));

		assertTrue(data.kcDays.isEmpty());
		assertEquals(Integer.valueOf(15), data.lastKnownKillCounts.get("Zulrah"));
		assertEquals("2026-07-13", data.lastKnownKillCountsAt);
	}

	@Test
	public void laggingHiscoresNeverReduceLocalState()
	{
		TrackerData data = new TrackerData();
		data.lastKnownKillCounts.put("Vorkath", 100);
		data.lastKnownKillCountsAt = "2026-07-15";

		assertEquals(0, killCountService.reconcile(data, LocalDate.parse("2026-07-15"), counts("Vorkath", 99)));
		assertEquals(Integer.valueOf(100), data.lastKnownKillCounts.get("Vorkath"));
		assertTrue(data.kcDays.isEmpty());
	}

	@Test
	public void lootFallbackAdvancesAKnownAbsoluteCount()
	{
		TrackerData data = new TrackerData();
		data.lastKnownKillCounts.put("Vorkath", 100);
		LocalDate today = LocalDate.parse("2026-07-15");

		killCountService.recordCompletion(data, today, "Vorkath", null);
		DailySummary live = summaryService.build(data, today, true).get(0);

		assertEquals(1, live.totalKills);
		assertEquals(Integer.valueOf(100), live.startingKillCounts.get("Vorkath"));
		assertEquals(Integer.valueOf(101), live.endingKillCounts.get("Vorkath"));
	}

	@Test
	public void excludesHiddenLootFromItemsAndConfirmedValue()
	{
		TrackerData data = new TrackerData();
		LocalDate today = LocalDate.parse("2026-07-15");
		TrackerData.LootDay day = new TrackerData.LootDay();
		TrackerData.LootSource source = new TrackerData.LootSource();
		TrackerData.LootItem visible = new TrackerData.LootItem(1, "Visible");
		visible.quantity = 1;
		visible.totalValue = 1_000L;
		visible.confirmedValue = 900L;
		TrackerData.LootItem hidden = new TrackerData.LootItem(2, "Hidden");
		hidden.quantity = 1;
		hidden.totalValue = 500L;
		hidden.confirmedValue = 400L;
		source.items.put(1, visible);
		source.items.put(2, hidden);
		source.totalValue = 1_000L;
		day.sources.put("Vorkath", source);
		data.lootDays.put(today.toString(), day);
		data.hiddenLootFor("Vorkath").add(2);

		DailySummary summary = summaryService.build(data, today, true).get(0);
		DailySummary.LootSummary loot = summary.findLoot("Vorkath");
		assertEquals(1_000L, summary.trackedLootValue);
		assertEquals(900L, summary.confirmedValue);
		assertEquals(1, loot.items.size());
		assertEquals(1, loot.hiddenItems.size());
		assertEquals(2, loot.hiddenItems.get(0).itemId);
	}

	@Test
	public void countsKeptLootAndUsesConfirmedValueOverride()
	{
		TrackerData data = new TrackerData();
		LocalDate today = LocalDate.parse("2026-07-15");
		TrackerData.LootDay day = new TrackerData.LootDay();
		TrackerData.LootSource source = new TrackerData.LootSource();
		TrackerData.LootItem kept = new TrackerData.LootItem(1, "Kept item");
		kept.quantity = 1;
		kept.totalValue = 600_000_000L;
		kept.kept = true;
		TrackerData.LootItem split = new TrackerData.LootItem(2, "Split item");
		split.quantity = 1;
		split.totalValue = 600_000_000L;
		split.confirmedValue = 600_000_000L;
		split.confirmedValueOverride = 200_000_000L;
		source.items.put(1, kept);
		source.items.put(2, split);
		source.totalValue = 1_200_000_000L;
		day.sources.put("Nex", source);
		data.lootDays.put(today.toString(), day);

		DailySummary summary = summaryService.build(data, today, true).get(0);
		assertEquals(200_000_000L, summary.confirmedValue);
		assertEquals(200_000_000L, summary.findLoot("Nex").items.get(1).confirmedValue);
	}

	@Test
	public void summarizesRaidPointsByDay()
	{
		TrackerData data = new TrackerData();
		TrackerData.RaidCompletion raid = new TrackerData.RaidCompletion();
		raid.date = "2026-07-15";
		raid.source = "Tombs of Amascut: Expert Mode";
		raid.personalPoints = 42_000;
		raid.lootPoints = 37_000;
		raid.raidLevel = 400;
		data.raidCompletions.add(raid);

		DailySummary summary = summaryService.build(data, LocalDate.parse("2026-07-15"), false).get(0);
		DailySummary.RaidSummary raids = summary.findRaid("Tombs of Amascut: Expert Mode");

		assertEquals(1, raids.completions);
		assertEquals(42_000L, raids.personalPoints);
		assertEquals(37_000L, raids.lootPoints);
		assertEquals(Integer.valueOf(400), raids.minimumRaidLevel);
	}

	private static Map<String, Integer> counts(Object... values)
	{
		Map<String, Integer> result = new LinkedHashMap<>();
		for (int i = 0; i < values.length; i += 2)
		{
			result.put((String) values[i], (Integer) values[i + 1]);
		}
		return result;
	}
}

package com.pvmtracker;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class GeSaleMatcherTest
{
	@Test
	public void matchesDelayedSaleToOldestLootFirst()
	{
		TrackerData data = new TrackerData();
		TrackerData.LootItem oldLoot = addLoot(data, "2026-07-10", "Nex", 4151, 2);
		TrackerData.LootItem newLoot = addLoot(data, "2026-07-14", "Abyssal Sire", 4151, 3);
		TrackerData.KillLootItem oldKillLoot = addKillLoot(data, "2026-07-10", "Nex", 4151, 2);
		TrackerData.KillLootItem newKillLoot = addKillLoot(data, "2026-07-14", "Abyssal Sire", 4151, 3);

		GeSaleMatcher.MatchResult match = GeSaleMatcher.match(data, 4151, 4, 4_000_000L);

		assertEquals(4, match.quantity);
		assertEquals(3_920_000L, match.value);
		assertEquals(2, oldLoot.confirmedQuantity);
		assertEquals(1_960_000L, oldLoot.confirmedValue);
		assertEquals(2, oldLoot.geConfirmedQuantity);
		assertEquals(1_960_000L, oldLoot.geConfirmedValue);
		assertEquals(2, newLoot.confirmedQuantity);
		assertEquals(1_960_000L, newLoot.confirmedValue);
		assertEquals(2, oldKillLoot.confirmedQuantity);
		assertEquals(1_960_000L, oldKillLoot.confirmedValue);
		assertEquals(2, newKillLoot.confirmedQuantity);
		assertEquals(1_960_000L, newKillLoot.confirmedValue);
	}

	@Test
	public void recordsHighAlchemyAsItsOwnConfirmationMethod()
	{
		TrackerData data = new TrackerData();
		TrackerData.LootItem loot = addLoot(data, "2026-07-10", "Vorkath", 11286, 1);

		GeSaleMatcher.MatchResult match = GeSaleMatcher.match(data, 11286, 1, 60_000L,
			GeSaleMatcher.ConfirmationMethod.HIGH_ALCHEMY);

		assertEquals(1, match.quantity);
		assertEquals(60_000L, loot.confirmedValue);
		assertEquals(1, loot.alchConfirmedQuantity);
		assertEquals(60_000L, loot.alchConfirmedValue);
		assertEquals(0, loot.geConfirmedQuantity);
	}

	@Test
	public void confirmsOnlyTheTrackedPartOfAMixedSale()
	{
		TrackerData data = new TrackerData();
		TrackerData.LootItem loot = addLoot(data, "2026-07-10", "Vorkath", 11286, 1);

		GeSaleMatcher.MatchResult match = GeSaleMatcher.match(data, 11286, 4, 8_000_000L);

		assertEquals(1, match.quantity);
		assertEquals(1_960_000L, match.value);
		assertEquals(1, loot.confirmedQuantity);
		assertEquals(1_960_000L, loot.confirmedValue);
	}

	@Test
	public void neverConfirmsTheSameLootTwice()
	{
		TrackerData data = new TrackerData();
		TrackerData.LootItem loot = addLoot(data, "2026-07-10", "Vorkath", 11286, 1);

		GeSaleMatcher.match(data, 11286, 1, 2_000_000L);
		GeSaleMatcher.MatchResult duplicate = GeSaleMatcher.match(data, 11286, 1, 3_000_000L);

		assertEquals(0, duplicate.quantity);
		assertEquals(0, duplicate.value);
		assertEquals(1, loot.confirmedQuantity);
		assertEquals(1_960_000L, loot.confirmedValue);
	}

	@Test
	public void recordsActualCoinsAfterGrandExchangeTax()
	{
		TrackerData data = new TrackerData();
		TrackerData.LootItem loot = addLoot(data, "2026-07-10", "Vorkath", 1619, 13);

		GeSaleMatcher.MatchResult match = GeSaleMatcher.match(data, 1619, 13, 14_976L);

		assertEquals(13, match.quantity);
		assertEquals(14_677L, match.value);
		assertEquals(14_677L, loot.confirmedValue);
		assertEquals(14_677L, loot.geConfirmedValue);
	}

	@Test
	public void roundsTaxDownPerItemAndCapsIt()
	{
		assertEquals(49L, GrandExchangeTax.netProceeds(1, 49L));
		assertEquals(49L, GrandExchangeTax.netProceeds(1, 50L));
		assertEquals(245_000_000L, GrandExchangeTax.netProceeds(1, 250_000_000L));
		assertEquals(295_000_000L, GrandExchangeTax.netProceeds(1, 300_000_000L));
	}

	private static TrackerData.LootItem addLoot(TrackerData data, String date, String boss, int itemId, long quantity)
	{
		TrackerData.LootDay day = data.lootDays.computeIfAbsent(date, ignored -> new TrackerData.LootDay());
		TrackerData.LootSource source = day.sources.computeIfAbsent(boss, ignored -> new TrackerData.LootSource());
		TrackerData.LootItem item = new TrackerData.LootItem(itemId, "Tracked item");
		item.quantity = quantity;
		item.totalValue = quantity * 1_500_000L;
		source.items.put(itemId, item);
		source.totalValue += item.totalValue;
		return item;
	}

	private static TrackerData.KillLootItem addKillLoot(TrackerData data, String date, String boss,
		int itemId, long quantity)
	{
		TrackerData.KillLogEntry kill = new TrackerData.KillLogEntry();
		kill.date = date;
		kill.source = boss;
		TrackerData.KillLootItem item = new TrackerData.KillLootItem(itemId, "Tracked item", quantity,
			quantity * 1_500_000L);
		kill.items.add(item);
		data.killLog.add(kill);
		return item;
	}
}

