package com.pvmtracker;

import com.google.gson.GsonBuilder;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.Buffer;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PvmHubUploaderTest
{
	@Test
	public void uploadsCompleteSnapshotAsJson() throws Exception
	{
		AtomicReference<Request> capturedRequest = new AtomicReference<>();
		AtomicReference<String> capturedBody = new AtomicReference<>();
		OkHttpClient client = new OkHttpClient.Builder()
			.addInterceptor(chain ->
			{
				Request request = chain.request();
				capturedRequest.set(request);
				Buffer buffer = new Buffer();
				request.body().writeTo(buffer);
				capturedBody.set(buffer.readUtf8());
				return new Response.Builder()
					.request(request)
					.protocol(Protocol.HTTP_1_1)
					.code(201)
					.message("Created")
					.body(ResponseBody.create(null, ""))
					.build();
			})
			.build();
		TrackerData snapshot = new TrackerData();
		snapshot.lastKnownName = "Logical";
		snapshot.lastKnownKillCounts.put("Vorkath", 42);
		TrackerData.KillLogEntry kill = new TrackerData.KillLogEntry();
		kill.id = "kill-1";
		kill.date = "2026-07-16";
		kill.source = "Tombs of Amascut: Expert Mode";
		kill.killCount = 42;
		kill.lootCaptured = false;
		snapshot.killLog.add(kill);
		TrackerData.RaidCompletion raid = new TrackerData.RaidCompletion();
		raid.id = "raid-1";
		raid.killId = "kill-1";
		raid.date = "2026-07-16";
		raid.occurredAt = "2026-07-17T06:25:41Z";
		raid.source = "Tombs of Amascut: Expert Mode";
		snapshot.raidCompletions.add(raid);
		CompletableFuture<Integer> result = new CompletableFuture<>();

		PvmHubUploader.uploadSnapshot(snapshot, new GsonBuilder().create(), client,
			(call, successful, responseCode) ->
			{
				if (successful)
				{
					result.complete(responseCode);
				}
				else
				{
					result.completeExceptionally(new AssertionError("Upload failed"));
				}
			});

		assertEquals(Integer.valueOf(201), result.get(5, TimeUnit.SECONDS));
		assertEquals(PvmHubUploader.UPLOAD_URL, capturedRequest.get().url().toString());
		assertEquals("POST", capturedRequest.get().method());
		assertEquals("application/json; charset=utf-8", capturedRequest.get().body().contentType().toString());
		TrackerData uploaded = new GsonBuilder().create().fromJson(capturedBody.get(), TrackerData.class);
		assertEquals("Logical", uploaded.lastKnownName);
		assertEquals(Integer.valueOf(42), uploaded.lastKnownKillCounts.get("Vorkath"));
		assertEquals("kill-1", uploaded.raidCompletions.get(0).killId);
		assertFalse(uploaded.killLog.get(0).hasCapturedLoot());
		assertEquals(5, uploaded.schemaVersion);
		assertTrue(capturedBody.get().contains("lootCaptured"));
		assertTrue(capturedBody.get().contains("killId"));
		assertFalse(capturedBody.get().contains("uniqueChance"));
		assertFalse(capturedBody.get().contains("expectedUniqueValue"));
		assertFalse(capturedBody.get().contains("estimateBasis"));
	}

	@Test
	public void uploadOptionIsOptInAndCarriesRequiredWarning() throws Exception
	{
		DailyPvmTrackerConfig config = new DailyPvmTrackerConfig()
		{
		};
		assertFalse(config.uploadToPvmHub());
		assertTrue(config.showEmptyDays());
		ConfigItem item = DailyPvmTrackerConfig.class.getMethod("uploadToPvmHub")
			.getAnnotation(ConfigItem.class);
		assertEquals("This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
			item.warning());
	}
}

package com.pvmtracker;

import java.util.Collections;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class RaidLootMatcherTest
{
	@Test
	public void ignoresVerzikPatientRecordButNotTheRewardChest()
	{
		assertTrue(RaidLootMatcher.isNonRewardLoot("Theatre of Blood", 1, ItemID.TOB_BOOK_VERZIK));
		assertFalse(RaidLootMatcher.isNonRewardLoot("Theatre of Blood", 1, ItemID.MOLTEN_GLASS));
		assertFalse(RaidLootMatcher.isNonRewardLoot("Theatre of Blood", 2, ItemID.TOB_BOOK_VERZIK));
	}

	@Test
	public void attributesGenericToaLootToNearbyExpertCompletion()
	{
		TrackerData.RaidCompletion completion = new TrackerData.RaidCompletion();
		completion.source = "Tombs of Amascut: Expert Mode";
		completion.occurredAt = "2026-07-17T06:25:41.901931200Z";

		assertEquals("Tombs of Amascut: Expert Mode", RaidLootMatcher.resolveSource(
			"Tombs of Amascut", "2026-07-17T06:26:02.896577800Z",
			Collections.singletonList(completion)));
	}

	@Test
	public void doesNotAttributeGenericToaLootToAnOldExpertCompletion()
	{
		TrackerData.RaidCompletion completion = new TrackerData.RaidCompletion();
		completion.source = "Tombs of Amascut: Expert Mode";
		completion.occurredAt = "2026-07-17T06:20:00Z";

		assertEquals("Tombs of Amascut", RaidLootMatcher.resolveSource(
			"Tombs of Amascut", "2026-07-17T06:26:02Z", Collections.singletonList(completion)));
	}

	@Test
	public void attributesOnlyGenericRaidSourcesToNearbyVariants()
	{
		TrackerData.RaidCompletion challengeCompletion = completion(
			"Chambers of Xeric: Challenge Mode", "2026-07-17T06:25:41Z");
		TrackerData.RaidCompletion entryCompletion = completion(
			"Theatre of Blood: Entry Mode", "2026-07-17T06:25:41Z");

		assertEquals("Chambers of Xeric: Challenge Mode", RaidLootMatcher.resolveSource(
			"Chambers of Xeric", "2026-07-17T06:26:02Z", Collections.singletonList(challengeCompletion)));
		assertEquals("Theatre of Blood: Entry Mode", RaidLootMatcher.resolveSource(
			"Theatre of Blood", "2026-07-17T06:26:02Z", Collections.singletonList(entryCompletion)));
	}

	@Test
	public void preservesSpecificRaidSourceNearDifferentVariantCompletion()
	{
		TrackerData.RaidCompletion normalToa = completion(
			"Tombs of Amascut", "2026-07-17T06:25:41Z");
		TrackerData.RaidCompletion normalCox = completion(
			"Chambers of Xeric", "2026-07-17T06:25:41Z");
		TrackerData.RaidCompletion normalTob = completion(
			"Theatre of Blood", "2026-07-17T06:25:41Z");

		assertEquals("Tombs of Amascut: Expert Mode", RaidLootMatcher.resolveSource(
			"Tombs of Amascut: Expert Mode", "2026-07-17T06:26:02Z", Collections.singletonList(normalToa)));
		assertEquals("Chambers of Xeric: Challenge Mode", RaidLootMatcher.resolveSource(
			"Chambers of Xeric: Challenge Mode", "2026-07-17T06:26:02Z", Collections.singletonList(normalCox)));
		assertEquals("Theatre of Blood: Hard Mode", RaidLootMatcher.resolveSource(
			"Theatre of Blood: Hard Mode", "2026-07-17T06:26:02Z", Collections.singletonList(normalTob)));
	}

	@Test
	public void repairsPreviouslyStoredGenericToaLootAndInferredNormalKc()
	{
		TrackerData data = new TrackerData();
		data.lastKnownKillCounts.put("Tombs of Amascut", 111);
		TrackerData.KcDay kcDay = new TrackerData.KcDay();
		kcDay.kills.put("Tombs of Amascut", 1);
		kcDay.startingKillCounts.put("Tombs of Amascut", 110);
		kcDay.endingKillCounts.put("Tombs of Amascut", 111);
		data.kcDays.put("2026-07-16", kcDay);
		TrackerData.LootDay lootDay = new TrackerData.LootDay();
		TrackerData.LootSource source = new TrackerData.LootSource();
		source.drops = 1;
		TrackerData.LootItem item = new TrackerData.LootItem(1615, "Dragonstone");
		item.quantity = 44;
		item.totalValue = 475_816L;
		source.items.put(item.itemId, item);
		lootDay.sources.put("Tombs of Amascut", source);
		data.lootDays.put("2026-07-16", lootDay);
		TrackerData.KillLogEntry kill = new TrackerData.KillLogEntry();
		kill.date = "2026-07-16";
		kill.occurredAt = "2026-07-17T06:26:02.896577800Z";
		kill.source = "Tombs of Amascut";
		kill.items.add(new TrackerData.KillLootItem(1615, "Dragonstone", 44, 475_816L));
		data.killLog.add(kill);
		TrackerData.RaidCompletion completion = new TrackerData.RaidCompletion();
		completion.source = "Tombs of Amascut: Expert Mode";
		completion.occurredAt = "2026-07-17T06:25:41.901931200Z";
		data.raidCompletions.add(completion);

		assertTrue(RaidLootMatcher.repairGenericRaidLootAttribution(data));
		assertEquals("Tombs of Amascut: Expert Mode", kill.source);
		assertFalse(lootDay.sources.containsKey("Tombs of Amascut"));
		assertEquals(1, lootDay.sources.get("Tombs of Amascut: Expert Mode").drops);
		assertFalse(kcDay.kills.containsKey("Tombs of Amascut"));
		assertEquals(Integer.valueOf(110), kcDay.endingKillCounts.get("Tombs of Amascut"));
		assertEquals(Integer.valueOf(110), data.lastKnownKillCounts.get("Tombs of Amascut"));
	}

	private static TrackerData.RaidCompletion completion(String source, String occurredAt)
	{
		TrackerData.RaidCompletion completion = new TrackerData.RaidCompletion();
		completion.source = source;
		completion.occurredAt = occurredAt;
		return completion;
	}
}

package com.pvmtracker;

import java.time.LocalDate;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class TrackerDataEditorTest
{
	private static final LocalDate DATE = LocalDate.parse("2026-07-15");

	@Test
	public void deletesSplitWithoutDeletingCapturedLoot()
	{
		TrackerData data = dataWithLootAndSplit();

		assertTrue(TrackerDataEditor.setSplit(data, DATE, "Nex", 0L));
		assertFalse(data.lootDays.get(DATE.toString()).sources.isEmpty());
		assertTrue(data.lootDays.get(DATE.toString()).manualAdjustments.isEmpty());
	}

	@Test
	public void deletesBossLootWithoutDeletingSplit()
	{
		TrackerData data = dataWithLootAndSplit();
		TrackerData.KillLogEntry kill = new TrackerData.KillLogEntry();
		kill.date = DATE.toString();
		kill.source = "Nex";
		kill.lootCaptured = true;
		kill.totalValue = 1_000L;
		kill.items.add(new TrackerData.KillLootItem(100, "Item", 1, 1_000L));
		data.killLog.add(kill);

		assertTrue(TrackerDataEditor.deleteBossLoot(data, DATE, "Nex"));
		assertTrue(data.lootDays.get(DATE.toString()).sources.isEmpty());
		assertFalse(data.lootDays.get(DATE.toString()).manualAdjustments.isEmpty());
		assertTrue(kill.items.isEmpty());
		assertEquals(0L, kill.totalValue);
		assertTrue(kill.hasCapturedLoot());
	}

	@Test
	public void deletesAllGpDataForDay()
	{
		TrackerData data = dataWithLootAndSplit();

		assertTrue(TrackerDataEditor.deleteDayGp(data, DATE));
		assertFalse(data.lootDays.containsKey(DATE.toString()));
	}

	@Test
	public void hidesAndRestoresAnItemForOnlyOneBoss()
	{
		TrackerData data = new TrackerData();
		TrackerData.LootDay day = new TrackerData.LootDay();
		TrackerData.LootSource nex = sourceWithItem(100, 1_000L);
		TrackerData.LootSource vorkath = sourceWithItem(100, 1_000L);
		day.sources.put("Nex", nex);
		day.sources.put("Vorkath", vorkath);
		data.lootDays.put(DATE.toString(), day);
		TrackerData.KillLogEntry kill = new TrackerData.KillLogEntry();
		kill.id = "kill-1";
		kill.date = DATE.toString();
		kill.occurredAt = "2026-07-15T20:00:00Z";
		kill.source = "Nex";
		kill.totalValue = 1_000L;
		kill.items.add(new TrackerData.KillLootItem(100, "Item", 1, 1_000L));
		data.killLog.add(kill);

		assertTrue(TrackerDataEditor.setLootHidden(data, "Nex", 100, true));
		assertTrue(data.isLootHidden("Nex", 100));
		assertFalse(data.isLootHidden("Vorkath", 100));
		assertEquals(0L, nex.totalValue);
		assertEquals(0L, kill.totalValue);
		assertEquals(1_000L, vorkath.totalValue);

		assertTrue(TrackerDataEditor.setLootHidden(data, "Nex", 100, false));
		assertEquals(1_000L, nex.totalValue);
		assertEquals(1_000L, kill.totalValue);
		assertFalse(data.hiddenLootItems.containsKey("Nex"));
	}

	@Test
	public void persistsKeptAndConfirmedValueOverrideForOneLootItem()
	{
		TrackerData data = new TrackerData();
		TrackerData.LootDay day = new TrackerData.LootDay();
		TrackerData.LootSource source = sourceWithItem(100, 600_000_000L);
		day.sources.put("Nex", source);
		data.lootDays.put(DATE.toString(), day);

		assertTrue(TrackerDataEditor.setLootKept(data, DATE, "Nex", 100, true));
		assertTrue(source.items.get(100).kept);
		assertTrue(TrackerDataEditor.setConfirmedValueOverride(data, DATE, "Nex", 100, 200_000_000L));
		assertEquals(Long.valueOf(200_000_000L), source.items.get(100).confirmedValueOverride);
		assertTrue(TrackerDataEditor.setConfirmedValueOverride(data, DATE, "Nex", 100, null));
		assertEquals(null, source.items.get(100).confirmedValueOverride);
	}

	private static TrackerData.LootSource sourceWithItem(int itemId, long value)
	{
		TrackerData.LootSource source = new TrackerData.LootSource();
		TrackerData.LootItem item = new TrackerData.LootItem(itemId, "Item");
		item.quantity = 1;
		item.totalValue = value;
		source.items.put(itemId, item);
		source.totalValue = value;
		return source;
	}

	private static TrackerData dataWithLootAndSplit()
	{
		TrackerData data = new TrackerData();
		TrackerData.LootDay day = new TrackerData.LootDay();
		day.sources.put("Nex", new TrackerData.LootSource());
		day.manualAdjustments.put("Nex", 10_000_000L);
		data.lootDays.put(DATE.toString(), day);
		return data;
	}
}

package com.pvmtracker;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TrackerDataMigrationTest
{
	@Test
	public void v5RemovesPreviouslyRecoveredKillsFromTheTimeline()
	{
		TrackerData data = new TrackerData();
		data.schemaVersion = 4;
		TrackerData.KcDay mixed = new TrackerData.KcDay();
		mixed.kills.put("Vorkath", 6);
		mixed.recoveredKills.put("Vorkath", 5);
		mixed.startingKillCounts.put("Vorkath", 100);
		mixed.endingKillCounts.put("Vorkath", 106);
		mixed.intervalEnd = "2026-07-19";
		data.kcDays.put("2026-07-18", mixed);

		TrackerData.KcDay recoveredOnly = new TrackerData.KcDay();
		recoveredOnly.kills.put("Zulrah", 3);
		recoveredOnly.recoveredKills.put("Zulrah", 3);
		recoveredOnly.startingKillCounts.put("Zulrah", 20);
		recoveredOnly.endingKillCounts.put("Zulrah", 23);
		data.kcDays.put("2026-07-17", recoveredOnly);

		assertTrue(TrackerDataMigration.migrateToCurrentVersion(data, 5));
		assertEquals(Integer.valueOf(1), mixed.kills.get("Vorkath"));
		assertEquals(Integer.valueOf(105), mixed.startingKillCounts.get("Vorkath"));
		assertTrue(mixed.recoveredKills.isEmpty());
		assertEquals(null, mixed.intervalEnd);
		assertTrue(recoveredOnly.kills.isEmpty());
		assertTrue(recoveredOnly.startingKillCounts.isEmpty());
		assertTrue(recoveredOnly.endingKillCounts.isEmpty());
	}

	@Test
	public void v4RemovesOnlyRaidCountsInferredBeyondExactLootCompletions()
	{
		TrackerData data = new TrackerData();
		data.schemaVersion = 3;
		TrackerData.KcDay day = new TrackerData.KcDay();
		day.kills.put("Chambers of Xeric", 2);
		day.recoveredKills.put("Chambers of Xeric", 1);
		day.startingKillCounts.put("Chambers of Xeric", 67);
		day.endingKillCounts.put("Chambers of Xeric", 69);
		data.kcDays.put("2026-07-17", day);
		TrackerData.KillLogEntry kill = new TrackerData.KillLogEntry();
		kill.date = "2026-07-17";
		kill.source = "Chambers of Xeric";
		kill.killCount = 69;
		data.killLog.add(kill);

		assertTrue(TrackerDataMigration.migrateToCurrentVersion(data, 4));
		assertEquals(4, data.schemaVersion);
		assertEquals(Integer.valueOf(1), day.kills.get("Chambers of Xeric"));
		assertFalse(day.recoveredKills.containsKey("Chambers of Xeric"));
		assertEquals(Integer.valueOf(68), day.startingKillCounts.get("Chambers of Xeric"));

		assertFalse(TrackerDataMigration.migrateToCurrentVersion(data, 4));
	}
}

package com.pvmtracker;

import com.google.gson.GsonBuilder;
import java.io.Reader;
import java.nio.file.Path;
import java.nio.file.Files;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertTrue;

public class TrackerStoreTest
{
	@Rule
	public TemporaryFolder temporaryFolder = new TemporaryFolder();

	@Test
	public void roundTripsSeparateCharacterFiles() throws Exception
	{
		Path directory = temporaryFolder.newFolder("daily-pvm-tracker").toPath();
		TrackerStore store = new TrackerStore(new GsonBuilder().create(), directory);
		TrackerData first = new TrackerData();
		first.lastKnownName = "One";
		first.lastKnownKillCounts.put("Vorkath", 42);
		TrackerData second = new TrackerData();
		second.lastKnownName = "Two";
		TrackerData.LootDay lootDay = new TrackerData.LootDay();
		lootDay.manualAdjustments.put("Nex", 12_500_000L);
		first.lootDays.put("2026-07-15", lootDay);
		TrackerData.RaidCompletion raid = new TrackerData.RaidCompletion();
		raid.id = "raid-1";
		raid.killId = "kill-1";
		raid.date = "2026-07-15";
		raid.source = "Chambers of Xeric";
		raid.personalPoints = 26_028;
		first.raidCompletions.add(raid);
		TrackerData.KillLogEntry kill = new TrackerData.KillLogEntry();
		kill.id = "kill-1";
		kill.date = "2026-07-15";
		kill.source = "Chambers of Xeric";
		kill.killCount = 42;
		kill.lootCaptured = false;
		first.killLog.add(kill);

		store.save(11L, first);
		store.save(22L, second);

		TrackerData loadedFirst = store.load(11L);
		TrackerData loadedSecond = store.load(22L);
		assertEquals(5, loadedFirst.schemaVersion);
		assertEquals("One", loadedFirst.lastKnownName);
		assertEquals(Integer.valueOf(42), loadedFirst.lastKnownKillCounts.get("Vorkath"));
		assertEquals(Long.valueOf(12_500_000L), loadedFirst.lootDays.get("2026-07-15").manualAdjustments.get("Nex"));
		assertEquals(Integer.valueOf(26_028), loadedFirst.raidCompletions.get(0).personalPoints);
		assertEquals("kill-1", loadedFirst.raidCompletions.get(0).killId);
		assertFalse(loadedFirst.killLog.get(0).hasCapturedLoot());
		assertEquals("Two", loadedSecond.lastKnownName);
		assertNotSame(loadedFirst, loadedSecond);
	}

	@Test
	public void appendsVersionToGeneratedProfileFileId() throws Exception
	{
		Path directory = temporaryFolder.newFolder("daily-pvm-tracker-versioned").toPath();
		TrackerStore store = new TrackerStore(new GsonBuilder().create(), directory);

		store.save(11L, new TrackerData());

		assertTrue(Files.exists(directory.resolve("11-v1.json")));
	}

	@Test
	public void closesLegacyProfileBeforePersistingV4Migration() throws Exception
	{
		Path directory = temporaryFolder.newFolder("daily-pvm-tracker-migration").toPath();
		Path profile = directory.resolve("11-v1.json");
		TrackerData legacy = new TrackerData();
		legacy.schemaVersion = 3;
		legacy.lastKnownName = "Logical";
		legacy.lastKnownKillCounts.put("Araxxor", 154);
		try (java.io.Writer writer = Files.newBufferedWriter(profile))
		{
			new GsonBuilder().create().toJson(legacy, writer);
		}

		TrackerData loaded = new TrackerStore(new GsonBuilder().create(), directory).load(11L);

		assertEquals(5, loaded.schemaVersion);
		assertEquals("Logical", loaded.lastKnownName);
		assertEquals(Integer.valueOf(154), loaded.lastKnownKillCounts.get("Araxxor"));
		try (Reader reader = Files.newBufferedReader(profile))
		{
			assertEquals(5, new GsonBuilder().create().fromJson(reader, TrackerData.class).schemaVersion);
		}
	}

	@Test
	public void ignoresUnversionedProfileFiles() throws Exception
	{
		Path directory = temporaryFolder.newFolder("daily-pvm-tracker-unversioned").toPath();
		TrackerStore store = new TrackerStore(new GsonBuilder().create(), directory);
		TrackerData oldData = new TrackerData();
		oldData.lastKnownName = "Old profile";
		try (java.io.Writer writer = Files.newBufferedWriter(directory.resolve("11.json")))
		{
			new GsonBuilder().create().toJson(oldData, writer);
		}

		assertEquals("", store.load(11L).lastKnownName);
	}

	@Test
	public void exportsWebsiteCompatibleSnapshot() throws Exception
	{
		Path directory = temporaryFolder.newFolder("daily-pvm-tracker-export").toPath();
		TrackerStore store = new TrackerStore(new GsonBuilder().create(), directory);
		TrackerData data = new TrackerData();
		data.lastKnownName = "Logical";
		data.lastKnownKillCounts.put("Vorkath", 42);
		TrackerData.KillLogEntry kill = new TrackerData.KillLogEntry();
		kill.id = "kill-1";
		kill.lootCaptured = false;
		data.killLog.add(kill);
		TrackerData.RaidCompletion raid = new TrackerData.RaidCompletion();
		raid.killId = "kill-1";
		data.raidCompletions.add(raid);
		Path destination = temporaryFolder.getRoot().toPath().resolve("daily-pvm-tracker-Logical.json");

		store.export(destination, data);

		assertTrue(java.nio.file.Files.exists(destination));
		TrackerData exported;
		try (Reader reader = java.nio.file.Files.newBufferedReader(destination))
		{
			exported = new GsonBuilder().create().fromJson(reader, TrackerData.class);
		}
		assertEquals(5, exported.schemaVersion);
		assertEquals("Logical", exported.lastKnownName);
		assertEquals(Integer.valueOf(42), exported.lastKnownKillCounts.get("Vorkath"));
		assertFalse(exported.killLog.get(0).hasCapturedLoot());
		assertEquals("kill-1", exported.raidCompletions.get(0).killId);
		String exportedJson = new String(Files.readAllBytes(destination), java.nio.charset.StandardCharsets.UTF_8);
		assertTrue(exportedJson.contains("lootCaptured"));
		assertTrue(exportedJson.contains("killId"));
	}

	@Test
	public void persistsHiddenLootRulesAndRecalculatesTotals() throws Exception
	{
		Path directory = temporaryFolder.newFolder("daily-pvm-tracker-hidden").toPath();
		TrackerStore store = new TrackerStore(new GsonBuilder().create(), directory);
		TrackerData data = new TrackerData();
		TrackerData.LootDay day = new TrackerData.LootDay();
		TrackerData.LootSource source = new TrackerData.LootSource();
		TrackerData.LootItem visible = new TrackerData.LootItem(1, "Visible");
		visible.quantity = 1;
		visible.totalValue = 1_000L;
		TrackerData.LootItem hidden = new TrackerData.LootItem(2, "Hidden");
		hidden.quantity = 1;
		hidden.totalValue = 500L;
		source.items.put(1, visible);
		source.items.put(2, hidden);
		source.totalValue = 9_999L;
		day.sources.put("Vorkath", source);
		data.lootDays.put("2026-07-15", day);
		data.hiddenLootFor("Vorkath").add(2);
		store.save(11L, data);

		TrackerData loaded = store.load(11L);
		assertTrue(loaded.isLootHidden("Vorkath", 2));
		assertEquals(1_000L, loaded.lootDays.get("2026-07-15").sources.get("Vorkath").totalValue);
	}
}
